def write_file(path, content):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w') as f:
        f.write(content)

for mod_id, mod_data in MODULES_06_15.items():
    base_dir = f"{BASE}/{mod_id}"
    os.makedirs(base_dir, exist_ok=True)
    
    write_file(f"{base_dir}/schema.js", mod_data["schema"])
    write_file(f"{base_dir}/controller.js", mod_data["controller"])
    write_file(f"{base_dir}/middleware.js", mod_data["middleware"])
    write_file(f"{base_dir}/routes.js", mod_data["routes"])
    write_file(f"{base_dir}/README.md", mod_data["readme"])
    write_file(f"{base_dir}/theory.md", mod_data["theory"])
    write_file(f"{base_dir}/checklist.md", mod_data["checklist"])
    write_file(f"{base_dir}/.env.example", "NODE_ENV=development\nPORT=4000\nLOG_LEVEL=info")
    write_file(f"{base_dir}/App.jsx", "import React from 'react';\nexport default function App() { return <div><h1>" + mod_data["name"] + "</h1></div>; }")
    
    print(f"✓ {mod_id}: {mod_data['name']}")

